:root {
  /* Colors */
  --color-linen-canvas: #f8f3f1;
  --color-parchment-wash: #f6f3f1;
  --color-paper-white: #ffffff;
  --color-frosted-cobalt: #cfdaf5;
  --color-jet-ink: #000000;
  --color-graphite-ink: #242424;
  --color-graphite-body: #242424cc;
  --color-graphite-caption: #24242499;
  --color-graphite-rule: #24242433;
  --color-graphite-hairline: #2424241a;
  --color-cobalt-signal: #2b59d1;

  /* Typography — Font Families */
  --font-abc-diatype-mono: "ABC Diatype Mono", "Geist Mono", "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-untitled-serif: "Untitled Serif", "Source Serif 4", "Newsreader", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-untitled-sans: "Untitled Sans", "Inter", "Public Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.2;
  --tracking-small: -0.4px;
  --text-caption: 16px;
  --leading-caption: 1.3;
  --tracking-caption: 0.8px;
  --text-body-sm: 16px;
  --leading-body-sm: 1.35;
  --tracking-body-sm: -0.4px;
  --text-body: 18px;
  --leading-body: 1.2;
  --tracking-body: -0.4px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.35;
  --tracking-body-lg: -0.4px;
  --text-subheading: 24px;
  --leading-subheading: 1.2;
  --tracking-subheading: -0.48px;
  --text-heading-sm: 32px;
  --leading-heading-sm: 1.2;
  --tracking-heading-sm: -0.64px;
  --text-heading: 40px;
  --leading-heading: 1.2;
  --tracking-heading: -0.8px;
  --text-heading-lg: 48px;
  --leading-heading-lg: 1.2;
  --tracking-heading-lg: -0.96px;
  --text-display: 80px;
  --leading-display: 1.2;
  --tracking-display: -1.6px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;

  /* Spacing */
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-30: 30px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-50: 50px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-100: 100px;
  --spacing-200: 200px;

  /* Layout */
  --layout-max-width: 1432px;
  --layout-content-width: 1352px;
  --layout-gutter: 40px;
  --layout-section-gap: 100px;
  --layout-section-gap-mobile: 64px;
  --layout-card-padding: 40px;
  --layout-element-gap: 16px;
  --layout-hero-title-width: 800px;
  --layout-hero-lede-width: 559px;
  --layout-nav-height: 122px;
  --layout-announcement-height: 62px;
  --layout-button-height: 44px;

  /* Border Radius */
  --radius-lg: 16px;
  --radius-3xl: 40px;
  --radius-full: 100px;
  --radius-full-2: 2000px;

  /* Named Radii */
  --radius-buttons: 100px;
  --radius-pills: 100px;
  --radius-tags: 100px;
  --radius-cards: 16px;
  --radius-sections: 40px;
  --radius-avatars: 50%;
  --radius-small-elements: 2000px;

  /* Shadows */
  --shadow-subtle: rgba(0, 0, 0, 0.1) 0px 0px 10px 0px;

  /* Surfaces */
  --surface-linen-canvas: #f8f3f1;
  --surface-parchment-wash: #f6f3f1;
  --surface-paper-white: #ffffff;
  --surface-frosted-cobalt: #cfdaf5;
  --surface-jet-ink: #000000;
}

